contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public {
        uint64 numberBefore = c.number();
        uint64 tsBefore = c.timestamp();
        uint256 feeBefore = c.basefee();
        bytes32 hashBefore = c.hash();
        uint64 seqBefore = c.sequenceNumber();
        bytes32 batcherBefore = c.batcherHash();
        uint256 overheadBefore = c.l1FeeOverhead();
        uint256 scalarBefore = c.l1FeeScalar();
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, s, b, o, sc) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(
            reverted &&
            c.number() == numberBefore &&
            c.timestamp() == tsBefore &&
            c.basefee() == feeBefore &&
            c.hash() == hashBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == batcherBefore &&
            c.l1FeeOverhead() == overheadBefore &&
            c.l1FeeScalar() == scalarBefore
        );
    }
}

